import React, { useEffect } from "react";

export default function UserDashboard() {
  useEffect(() => {
    const token = localStorage.getItem("accessToken");
    if (!token) {
      window.location.href = "/login";
    }
  }, []);

  return (
    <div>
      <h1>User Dashboard</h1>
      <p>Welcome, user!</p>
    </div>
  );
}
